import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
import math
PG.configure('/festivals/ratha-saptami/',[('','Ratha Saptamī','The Sun’s Chariot Turns North')],'navy','Ratha Saptamī','Lord','Ratha Saptamī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/ratha-saptami/'
i=0
HC=['#c0392b','#ff8c1a','#ffd60a','#2a9d6f','#1d6fb8','#3a3aa0','#7a3fa0']
def horse(c): return f'<ellipse cy="-18" rx="16" ry="8" fill="{c}"/><path d="M14 -22 l10 -12 l4 4 l-6 10z" fill="{c}"/><path d="M-10 -12 l-3 12 M10 -12 l3 12" stroke-width="2"/>'
def chariot(): return ''.join(g(-150+k*24,0,.9,horse(HC[k])) for k in range(7))+'<path d="M30 -10 h60 v-40 h-60z" fill="#e0a800"/><circle cx="60" cy="0" r="14" fill="#fff8e7"/>'+''.join(f'<path d="M60 0 l{14*math.cos(a):.1f} {14*math.sin(a):.1f}" stroke-width="1.5"/>' for a in [k*math.pi/6 for k in range(12)])+g(60,-56,.7,sun(18))+g(20,-14,.6,god('#c0582a'))
def arka(): return '<path d="M0 0 q-12 -14 0 -34 q12 20 0 34z" fill="#8fb89a" stroke="#4a7a5a"/><path d="M0 0 v-34" stroke="#4a7a5a" stroke-width="1"/>'
def arka_person(): return person('#2a5aa8')+g(0,-52,.5,arka())+g(-10,-34,.4,arka())+g(10,-34,.4,arka())
def rangoli_chariot(): return '<rect x="-70" y="-30" width="140" height="40" rx="6" fill="none" stroke="#c0392b" stroke-width="3" stroke-dasharray="4 3"/>'+''.join(f'<circle cx="{-60+k*16}" cy="-10" r="5" fill="{HC[k]}"/>' for k in range(7))+'<circle cx="54" cy="-10" r="12" fill="#ffd60a"/>'
def egg(): return '<ellipse rx="14" ry="18" fill="#f4ecd8"/>'
COV=covart('The sun’s chariot drawn by seven coloured horses across a dawn sky, with Aruṇa as charioteer, above a river where people bathe with leaves on their heads',f'<rect width="440" height="196" fill="#fde9c8"/>'+'<rect y="150" width="440" height="46" fill="#8fb8de"/>'+g(250,110,1.15,chariot())+''.join(g(x,180,.9,arka_person()) for x in (80,150,320,390)))
pp=[foreword(i,['On the seventh day of the bright fortnight of Māgha, the sun’s chariot is said to turn north in earnest. <b>Ratha Saptamī</b> is the Sun’s birthday (<b>Sūrya Jayantī</b>) and, in the South, the day for the strangest bath of the year: before dawn, with seven leaves of the wild <b>arka</b> plant on the head, shoulders, knees and feet.','This article explains the chariot and its seven horses, tells the birth of the Sun to Aditi and the story of his lame charioteer Aruṇa, the healing stories of the day, gives the bath verse and the Gāyatrī, and goes to the temples that celebrate it grandly: Tirumala with seven processions in one day, Mēlukōṭe, Śrīraṅgapaṭṭaṇa, Mangaluru and the great sun temples of India.'],[('z','The sun has a birthday?'),('b','Two of them, in a way, Zappy: Saṅkrānti when his course turns, and Ratha Saptamī when his chariot is said to set out. This one is the birthday.')]),
 glance([('Name','Ratha Saptamī; Sūrya Jayantī; Māgha Saptamī; Acalā Saptamī'),('When','Māgha Śukla Saptamī, the 7th of the bright fortnight of Māgha (January–February), about three weeks after Makara Saṅkrānti'),('Deity','Sūrya, the Sun, son of Kaśyapa and Aditi'),('The bath','At aruṇodaya, before sunrise, with seven arka (ekka) leaves'),('At home','Rangoli of a chariot with seven horses; milk boiled over in the sun; arghya; Āditya Hṛdayam'),('Temples','Tirumala’s one-day Brahmotsava; Mēlukōṭe; Śrīraṅgapaṭṇa; Mangaluru’s Koḍiyāl Tēru; Arasavalli; Konark; Modhera'),('Next day','Bhīṣma Aṣṭamī')],svg(560,140,'The sun’s chariot with seven horses',f'<rect width="560" height="140" fill="#fde9c8"/>'+g(330,110,1,chariot()))),
 reading('chariot','THE CHARIOT AND THE SEVEN HORSES','What the image means',svg(560,170,'A chariot with one wheel of twelve spokes, drawn by seven horses in seven colours, with Aruṇa driving',f'<rect width="560" height="170" fill="#fde9c8"/>'+g(330,140,1.4,chariot())),['<b>The chariot.</b> The Sun rides across the sky in a golden chariot. Many images give it a single wheel, which the Vedic hymns already know; its twelve spokes are often read as the twelve months or the twelve signs of the zodiac, the wheel as the year.','<b>Seven horses.</b> Seven horses draw it, often named after the seven Vedic metres (Gāyatrī, Triṣṭubh, Jagatī…). Many read them as the seven colours of the spectrum or the seven days of the week, starting with Sunday. (Interpretations.)','<b>Aruṇa.</b> The charioteer is <b>Aruṇa</b>, the dawn, red and without thighs (next pages tell why), brother of Garuḍa.','<b>Why “Ratha Saptamī”.</b> On this day, tradition says, the Sun’s chariot turns fully northward and the warmth of spring begins. The name also marks the start of the temple car-festival (<i>rathotsava</i>) season in uttarāyaṇa.'],[('z','Seven horses for seven colours?'),('b','That’s one modern reading, Zappy. The old one says seven metres of the Veda pull the sun. Both are lovely.')],'Seven horses, <b>one wheel of the year</b>.'),
 story('aditi','THE SUN IS BORN','Aditi’s son, Mārtaṇḍa',strip('Three panels: Aditi in penance; a golden egg that seemed lifeless; the radiant Sun bursting forth',[panel([(person('#c0392b'),1),(sage('#ff8c1a'),.8)],'#fff3cf',150),panel([(egg(),1.6)],'#e9e3f5',150),panel([(sun(26),1.4)],'#fde9c8',150)],['Aditi’s tapas','the “dead” egg','Mārtaṇḍa shines']),'Purāṇic tellings of the Sun’s birth; details differ.',['<b>Aditi</b>, mother of the gods and wife of the sage <b>Kaśyapa</b>, saw her sons the devas defeated by the demons and prayed to the Sun to be born as her son and protect them.','She conceived, and kept fierce vows while pregnant. Kaśyapa, worried, asked her angrily whether she meant to kill the child in her womb (<i>mṛtam aṇḍam</i>, “a dead egg”).','In answer she brought forth the embryo, and it shone like a mass of fire: the Sun himself, called <b>Mārtaṇḍa</b>, “born from the dead egg”.','Grown, Sūrya defeated the demons and restored the gods. As one of Aditi’s twelve sons, the Ādityas, he is <b>Āditya</b>.','Tradition holds that this birth fell on Māgha Śukla Saptamī: hence <b>Sūrya Jayantī</b>.'],[('z','The sun came from an egg people thought was dead?'),('b','That’s what Mārtaṇḍa means, Zappy. Life from what looked lifeless: a good thing to remember in winter.')],'Light from <b>a “dead” egg</b>.'),
 story('aruna','WHY ARUṆA HAS NO LEGS','The charioteer of dawn',strip('Three panels: Vinatā breaking an egg early; Aruṇa emerging half-formed and cursing his mother; Aruṇa driving the Sun’s chariot',[panel([(person('#e0a800'),1),(egg(),1)],'#fff3cf',150),panel([(god('#c0392b'),.9),(person('#e0a800'),.8)],'#fde4e4',150),panel([(horse('#c0392b'),1),(god('#c0392b'),.8),(sun(14),1)],'#fde9c8',150)],['an egg broken early','half-formed','the dawn’s charioteer']),'Mahābhārata, Ādi Parvan (the same chapters as Kadru and Vinatā; read our '+L('/festivals/naga-panchami/','Nāga Pañcamī article')+').',['<b>Vinatā</b>, Kaśyapa’s wife, laid two eggs. Her sister Kadru’s thousand serpent eggs had already hatched; impatient, Vinatā broke open one of hers early.','Out came <b>Aruṇa</b>, glowing red but only half-formed: he had no thighs or legs.','Angry, he told his mother she would become her sister’s slave for her impatience, and that the second egg, if left alone, would bring a son to free her: that son was <b>Garuḍa</b>.','Aruṇa rose into the sky and became the <b>charioteer of the Sun</b>: the red glow before sunrise is Aruṇa, going ahead of his master.','So the bath of Ratha Saptamī is taken at <b>aruṇodaya</b>, “the rising of Aruṇa”, the red hour before the sun appears.'],[('z','A charioteer without legs?'),('b','Who needs legs when you drive the sun, Zappy? And he teaches patience: the egg that waited became Garuḍa.')],'The dawn <b>drives the day</b>.'),
 reading('bath','THE ARKA BATH','Seven leaves before sunrise',svg(560,170,'A person standing in a river at dawn with arka leaves on the head, shoulders and feet, and the sun just rising',f'<rect width="560" height="170" fill="#fde9c8"/>'+g(420,110,1.4,sun(24))+'<rect y="110" width="560" height="60" fill="#8fb8de"/>'+g(200,150,1.6,arka_person())+g(300,140,1.4,arka())),['<b>The time.</b> The bath is taken at <b>aruṇodaya</b>, the red hour before sunrise, ideally in a river, a tank or the sea; at home, from a pot of water filled the night before.','<b>The leaves.</b> Seven leaves of <b>arka</b> (Calotropis gigantea; <b>ekka</b> in Kannada, erukku in Tamil, jilleḍu in Telugu) are placed on the body, commonly one on the head, two on the shoulders, two on the knees and two on the feet, often with a few grains of rice and a pinch of turmeric or sesame, and water is poured over them while the verse on the next page is said.','<b>Why arka.</b> <i>Arka</i> is itself a name of the Sun: the plant is to the Sun what tulasī is to Viṣṇu and bilva to Śiva. Its milky sap is irritant, so the leaves are used whole and washed off.','<b>Arghya.</b> After the bath, water is offered to the rising sun from cupped hands, often with red flowers and red sandal: <b>arghya</b>. Many follow with Sūrya namaskāra.'],[('z','What is arka?'),('b','A tough wild shrub with big grey-green leaves, Zappy. It grows on every roadside in Karnataka. Be gentle with the sap.')],'Seven leaves <b>for the seven horses</b>.'),
 verse('v-snana','The Ratha Saptamī bath verse','Said as the water is poured',['yad yaj janmakṛtaṃ pāpaṃ mayā saptasu janmasu','tan me rogaṃ ca śokaṃ ca mākarī hantu saptamī'],svg(200,150,'Water pouring over arka leaves on a head at dawn',f'<rect width="200" height="150" fill="#fde9c8"/>'+g(150,60,1,sun(20))+g(80,140,1.3,arka_person())+'<path d="M70 40 q4 20 0 40 M84 40 q4 20 0 40" stroke="#8fb8de" stroke-width="3" fill="none"/>'),'Whatever sin I have committed in seven births, may this Saptamī of Makara (the sun in Capricorn) destroy it, and with it my disease and my sorrow.',[('yad yat','whatever'),('janma-kṛtam','done in a birth'),('saptasu janmasu','in seven births'),('rogam','disease'),('śokam','sorrow'),('mākarī saptamī','the Saptamī when the sun is in Makara')],'<b>Seven by seven.</b> The day is full of sevens: the seventh tithi, seven horses, seven leaves, sins of seven births. The verse names the day <i>mākarī</i> because the sun is then in Makara, the sign it entered at Saṅkrānti three weeks earlier. Many families continue with further lines asking the Sun to accept the arghya.',k='Seven births, <b>one bath</b>.',note='A household verse as given in many Ratha Saptamī guides (e.g. astroved.com, hindupad.com), with variations; we have not traced it to a single text.'),
 story('samba','THE HEALING STORIES','Sāmba, and the king’s son',strip('Three panels: Sāmba struck by illness; Sāmba worshipping the Sun by a river; a king’s son recovering after the Ratha Saptamī vow',[panel([(god('#7a3fa0'),1),('<circle r="4" fill="#c0392b"/><circle cx="8" cy="-10" r="3" fill="#c0392b"/>',1)],'#e9e3f5',150),panel([(god('#7a3fa0'),.9),(sun(18),1),(river(144,150),1)],'#fde9c8',None),panel([(god('#e0a800'),.9),(child(),.8)],'#fff3cf',150)],['Sāmba’s illness','worship of the Sun','the prince restored']),'Purāṇic and vrata-book traditions; details vary.',['<b>Sāmba</b>, son of Kṛṣṇa and Jāmbavatī, was struck by a skin disease, by a curse according to the Purāṇic tellings.','He was told to worship the Sun. By the Candrabhāgā river he did so for years, and was cured; in gratitude, tradition says, he built a great sun temple (Mūlasthāna, Multan, and in Odia tradition the site later called Konark is linked with him too).','A second story, told in vrata books: <b>Yaśovarmā</b>, a childless king of Kāmbhoja, at last had a son, who fell gravely ill.','A sage advised the Ratha Saptamī worship. The prince kept it, recovered, and ruled long and well.','So the day is kept for <b>health</b> above all: the bath, the sunlight and the sun-plant at the turn from winter to spring.'],[('z','The sun heals?'),('b','The tradition says so, Zappy, and every grandmother sends you out into the morning sun in winter. They’re not wrong.')],'Light <b>for health</b>.'),
 verse('v-gayatri','The Gāyatrī','The Sun as Savitṛ',['oṃ bhūr bhuvaḥ svaḥ','tat savitur vareṇyaṃ','bhargo devasya dhīmahi','dhiyo yo naḥ pracodayāt'],svg(200,150,'The rising sun with rays reaching a meditating figure',f'<rect width="200" height="150" fill="#fde9c8"/>'+g(140,60,1.3,sun(24))+g(60,140,1,sage('#ff8c1a'))+''.join(f'<path d="M120 70 l{-40-k*10} {40+k*6}" stroke="#ffd60a" stroke-width="2"/>' for k in range(3))),'We meditate on that most excellent radiance of the god Savitṛ (the Sun as impeller); may he stir our minds.',[('savituḥ','of Savitṛ, the Sun'),('vareṇyam','most excellent'),('bhargaḥ','radiance'),('dhīmahi','we meditate'),('dhiyaḥ','minds, thoughts'),('pracodayāt','may he stir')],'<b>The Veda’s sun prayer.</b> The Gāyatrī (Ṛgveda 3.62.10) is addressed to Savitṛ, the Sun. On Ratha Saptamī many recite it at sunrise with arghya, and it is the heart of the sandhyā worship done at dawn, noon and dusk. Note what it asks for: not wealth or health, but a stirred mind.',k='Ask the Sun <b>to wake the mind</b>.',note='Text as on our '+L('/devi/gayatri-mantra/','Gāyatrī Mantra')+' page.'),
 reading('home','AT HOME','Rangoli, milk boiled over and the Āditya Hṛdayam',svg(560,160,'A rangoli of a chariot at a doorstep and a pot of milk boiling over on a small fire in the sun',f'<rect width="560" height="160" fill="#fde9c8"/>'+'<rect y="110" width="560" height="50" fill="#e9d6c0"/>'+g(200,140,1.3,rangoli_chariot())+g(420,140,1,fire())+g(420,108,1,pot('#c98a5a'))+'<path d="M408 86 q-6 10 -2 20 M432 86 q6 10 2 20" stroke="#fff" stroke-width="4" fill="none"/>'+g(500,40,1,sun(18))),['<b>The chariot rangoli.</b> At the door, a rangoli of the Sun’s chariot with seven horses is drawn in coloured powder; many place a cow-dung cake at its centre and light it.','<b>Milk in the sun.</b> In many South Indian homes milk is boiled in the open courtyard, on that fire or in the sun’s sight, until it froths over, and sweet pongal or pāyasa made from it is offered to the Sun: the same gesture as Saṅkrānti’s pongal.','<b>The hymns.</b> Families recite the <b>Āditya Hṛdayam</b>, the hymn the sage Agastya taught Rāma before his last battle (Rāmāyaṇa, Yuddha Kāṇḍa), the Sūryāṣṭakam, or the twelve names of the Sun used in Sūrya namaskāra (Mitra, Ravi, Sūrya, Bhānu, Khaga, Pūṣan, Hiraṇyagarbha, Marīci, Āditya, Savitṛ, Arka, Bhāskara).','<b>Giving.</b> Many give sesame, blankets, umbrellas, āmalaka fruit or clothes on this day, as at Saṅkrānti.'],[('z','What is the Āditya Hṛdayam?'),('b','A hymn to the sun in the Rāmāyaṇa, Zappy, taught to a tired Rāma before he faced Rāvaṇa. A good one for a future guide.')],'Milk <b>boiled over in the sun</b>.'),
 cards('temples','THE TEMPLES CELEBRATE','Seven processions in a day',fig_row('Seven small vehicles in a row: sun halo, serpent, Garuḍa, Hanumān, tree, king, moon',[(sun(14),1.4),(cobra() if False else '<path d="M-14 0 q-10 -30 14 -40 q20 10 0 40" fill="#2a6a3a"/>',1),(bird('#c0582a'),1.4),(hanuman(),.7),(tree(),.6),(god('#e0a800'),.7),(moon(),1)],['Sūryaprabhā','Śeṣa','Garuḍa','Hanumān','Kalpavṛkṣa','Sarvabhūpāla','Candraprabhā'],gy=150),[('🛕','Tirumala','The <b>one-day Brahmotsava</b>: Malayappasvāmī with Śrīdevī and Bhūdevī goes round the Māḍa streets on seven vāhanas between sunrise (Sūryaprabhā, the sun’s halo) and night (Candraprabhā, the moon’s halo), with a midday bath of the discus.'),('⛰️','Near Mysuru','<b>Mēlukōṭe</b> carries the Sūryamaṇḍala in procession; the Raṅganātha temple of <b>Śrīraṅgapaṭṇa</b> keeps its own Ratha Saptamī festival. See our '+L('/temples-of-india/around-mysuru/melukote/','Mēlukōṭe')+' guide.'),('🚩','Mangaluru','The car festival of the Śrī Veṅkaṭaramaṇa temple, the <b>Koḍiyāl Tēru</b> of the Konkani community, falls at this season.'),('☀️','Sun temples','Arasavalli (Śrīkākuḷam), Konark (Odisha), Modhera (Gujarat), Sūryanār Kōvil near Kumbakōṇam all celebrate grandly.')],[('z','All seven processions in one day?'),('b','Dawn to night, Zappy. In the big Brahmotsava he rides only one or two a day. This is the express version.')],'Dawn to night, <b>seven rides</b>.'),
 reading('bhishma','BHĪṢMA AṢṬAMĪ','The next day',svg(560,150,'A warrior on a bed of arrows with the sun high and northward',f'<rect width="560" height="150" fill="#fde9c8"/>'+g(440,40,1,sun(20))+'<rect y="125" width="560" height="25" fill="#e9d6c0"/>'+g(240,120,1.4,'<rect x="-60" y="-10" width="120" height="8" fill="#8a5a3a"/>'+''.join(f'<path d="M{x} -2 l{(-1)**int(x/10)*6} 28" stroke-width="1.6"/>' for x in range(-56,60,8))+'<path d="M-50 -16 h90" stroke="#c98a5a" stroke-width="10"/><circle cx="48" cy="-18" r="9" fill="#f2c79b"/>')),['<b>The day after.</b> Māgha Śukla Aṣṭamī, the day after Ratha Saptamī, is <b>Bhīṣma Aṣṭamī</b>: by tradition the day the grandsire Bhīṣma, having waited on his bed of arrows for the sun’s northern course, gave up his body.','<b>Tarpaṇa for Bhīṣma.</b> Bhīṣma had no children; tradition asks everyone to offer water (tarpaṇa) to him on this day, as to an ancestor of all.','<b>The link.</b> The sun’s turn north, marked at '+L('/festivals/makara-sankranti/','Makara Saṅkrānti')+' and fulfilled on Ratha Saptamī, was the moment Bhīṣma waited for. The two festivals belong together.','<b>A season of chariots.</b> From here the temple car festivals of spring begin in many parts of the South.'],[('z','Everyone offers water to Bhīṣma?'),('b','He had no sons to do it, Zappy, so all of India does. That’s how the tradition honours him.')],'The grandsire <b>departs in the light</b>.'),
 reading('meaning','WHAT RATHA SAPTAMĪ MEANS','Light, health and time',svg(560,150,'The sun on its chariot over green fields with a family offering water',f'<rect width="560" height="150" fill="#fde9c8"/>'+'<rect y="115" width="560" height="35" fill="#a8c890"/>'+g(380,90,.8,chariot())+g(120,120,1,namaste('#c0392b'))+g(170,120,.9,child())),['<b>Gratitude.</b> All life on earth depends on the Sun; Ratha Saptamī is the day to say so, with water, leaves and light.','<b>Health.</b> The early bath, the sun-plant and the morning sun at the end of winter: the festival is a lesson in seasonal care, and its stories are about healing.','<b>Time.</b> The Sun is the maker of days, months and years: his chariot-wheel is the year itself. The festival keeps the calendar of the seasons, as the lunar festivals keep the calendar of the moon.','<b>The mind.</b> The Gāyatrī asks the Sun to stir our thinking. Many teachers read the outer sun as a picture of inner awareness that never sets. (Interpretation.)'],[('z','If I could do one thing for Ratha Saptamī?'),('b','Wake before sunrise, Zappy, bathe, offer a little water to the rising sun, and say the Gāyatrī once with your whole attention.')],'Thank the light, <b>wake the mind</b>.'),
 end(i,['<b>When.</b> Māgha Śukla Saptamī, the Sun’s birthday.','<b>Image.</b> One wheel of twelve spokes, seven horses, Aruṇa the dawn.','<b>Stories.</b> Mārtaṇḍa from the “dead” egg; Aruṇa and Garuḍa; Sāmba healed.','<b>Bath.</b> Seven arka leaves at aruṇodaya; the bath verse; arghya; Gāyatrī.','<b>Temples.</b> Tirumala’s seven vāhanas; Mēlukōṭe; Konark. Next day, Bhīṣma Aṣṭamī.'],'Previous: '+L('/festivals/makara-sankranti/','Makara Saṅkrānti')+'. Next: '+L('/festivals/maha-shivaratri/','Mahāśivarātri')+'.','Ratha Saptamī: the Sun’s chariot'),
 sources([('Customs and temples:','Wikipedia, “Ratha Saptami” (date, Sūrya Jayantī, seven horses and twelve-spoked wheel, arka bath with seven leaves, Yaśovarmā story, chariot rangoli, milk boiled in the sun, Tirumala seven vāhanas, Arasavalli, Konark, Modhera, Mangaluru Koḍiyāl Tēru, Mysuru and Mēlukōṭe processions).'),('Texts:','Mahābhārata, Ādi Parvan (Vinatā, Aruṇa, Garuḍa); Purāṇic tellings of Mārtaṇḍa and of Sāmba; Ṛgveda 3.62.10 (Gāyatrī, from our own page); Rāmāyaṇa, Yuddha Kāṇḍa (Āditya Hṛdayam). Bath verse from popular guides.')],'the date of the Sun’s birth (tradition); Sāmba’s temples (traditions differ); the Yaśovarmā story (vrata books); the bath verse’s source; readings of the seven horses (modern and traditional interpretations).','Interpretations are marked as such.')]
build(i,'SŪRYA JAYANTĪ · SEVEN HORSES · THE ARKA BATH',COV,'Seven horses at dawn','The <b>chariot</b> and its seven horses, the <b>stories</b> of the Sun’s birth, Aruṇa and the healings, the <b>arka bath</b> and its verse, the Gāyatrī, and the <b>temples</b> from Tirumala to Mēlukōṭe.','Ratha Saptamī explained: Māgha Śukla Saptamī as Sūrya Jayantī, the Sun’s chariot with seven horses, Mārtaṇḍa and Aditi, Aruṇa the charioteer, the arka-leaf bath at aruṇodaya with its verse, the Gāyatrī, Sāmba’s healing, Tirumala’s seven vāhanas, Mēlukōṭe and Bhīṣma Aṣṭamī.',pp)
print('ratha ok',len(pp)+2)
